import axios from "axios";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

export const fetchCartItems = async (accessToken: string | null) => {
  if (!accessToken) {
    throw new Error("Please log in to view your cart.");
  }

  try {
    const response = await axios.get(`${API_BASE_URL}/carts/active/products`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    if (response.data.success) {
      return response.data.data;
    } else {
      throw new Error("Failed to fetch cart items.");
    }
  } catch (err) {
    console.error("Error fetching cart items:", err);
    throw new Error("Error fetching cart data. Please try again.");
  }
};

export const increaseCartItemQuantity = async (productId: number, accessToken: string | null) => {
  if (!accessToken) return;

  try {
    await axios.put(
      `${API_BASE_URL}/carts/add`,
      {},
      {
        params: { productId },
        headers: { Authorization: `Bearer ${accessToken}` },
      }
    );

    window.dispatchEvent(new Event("storage"));
  } catch (err) {
    console.error("Error increasing quantity:", err);
  }
};

export const decreaseCartItemQuantity = async (
  productId: number,
  currentQuantity: number,
  accessToken: string | null
) => {
  if (!accessToken || currentQuantity === 1) return;

  try {
    await axios.put(
      `${API_BASE_URL}/carts/subtract`,
      {},
      {
        params: { productId },
        headers: { Authorization: `Bearer ${accessToken}` },
      }
    );

    window.dispatchEvent(new Event("storage"));
  } catch (err) {
    console.error("Error decreasing quantity:", err);
  }
};

export const removeCartItem = async (cartItemId: number, accessToken: string | null) => {
  if (!accessToken) return;

  try {
    await axios.delete(`${API_BASE_URL}/carts/remove`, {
      params: { cartItemId },
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    window.dispatchEvent(new Event("storage"));
  } catch (err) {
    console.error("Error removing item:", err);
  }
};
